IF NOT `v_related_product` <=> NEW.`product_id` THEN
SIGNAL SQLSTATE '23000' SET MYSQL_ERRNO=3819, MESSAGE_TEXT='Lot SKU mismatch';
END IF;
END IF;
IF NEW.`serial_id` IS NOT NULL THEN
SELECT `product_id` INTO v_related_product FROM `serial` WHERE NEW.`serial_id` = `id` FOR UPDATE;
IF NOT `v_related_product` <=> NEW.`product_id` THEN
